/* ==UserStyle==
@name freedesktop.org Catppuccin
@namespace github.com/catppuccin/userstyles/styles/freedesktop
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/freedesktop
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/freedesktop/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Afreedesktop
@description Soothing pastel theme for freedesktop.org
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("www.freedesktop.org"),
  domain("specifications.freedesktop.org") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      background-color: @base;
      color: @text;
    }

    #content h1,
    #content h2,
    #content h3,
    #content h4,
    #content h5,
    #content h6 {
      color: @accent;
    }

    .pageheader {
      background-color: @mantle;
      border-color: @crust;
      color: @subtext1;
    }

    .pageheader .actions ul li a,
    input[type="submit"] {
      background-color: transparent;
      color: @accent;
      border-color: @accent;
    }

    input#searchbox {
      color: @subtext1;
      background-color: @overlay0;
      border-color: @overlay1;
      box-shadow: none;
      &:focus {
        border-color: @accent;
        outline-color: none;
        outline-style: none;
      }
    }

    .headerpath .title {
      color: @subtext1;
    }

    a:link {
      color: @blue;
    }

    a:visited {
      color: @lavender;
    }
    code {
      background-color: @crust;
      color: @text;
    }

    pre {
      background-color: @mantle;
      border-color: @surface0;

      code {
        background-color: @mantle;
        color: @text;
      }
    }

    hr {
      border-style: solid;
      border-color: @surface1;
    }

    .topnav, tr:nth-child(2n+1) {
      border-color: @surface0;
      background-color: @mantle;
    }
  }
}

