@media (prefers-color-scheme: light) {
  :root {
    color-scheme: light;
  }
  :root ::selection {
    background-color: rgba(136, 57, 239, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #6c6f85 !important;
  }
  :root body {
    background-color: #eff1f5;
    color: #4c4f69;
  }
  :root #content h1,
  :root #content h2,
  :root #content h3,
  :root #content h4,
  :root #content h5,
  :root #content h6 {
    color: #8839ef;
  }
  :root .pageheader {
    background-color: #e6e9ef;
    border-color: #dce0e8;
    color: #5c5f77;
  }
  :root .pageheader .actions ul li a,
  :root input[type="submit"] {
    background-color: transparent;
    color: #8839ef;
    border-color: #8839ef;
  }
  :root input#searchbox {
    color: #5c5f77;
    background-color: #9ca0b0;
    border-color: #8c8fa1;
    box-shadow: none;
  }
  :root input#searchbox:focus {
    border-color: #8839ef;
    outline-color: none;
    outline-style: none;
  }
  :root .headerpath .title {
    color: #5c5f77;
  }
  :root a:link {
    color: #1e66f5;
  }
  :root a:visited {
    color: #7287fd;
  }
  :root code {
    background-color: #dce0e8;
    color: #4c4f69;
  }
  :root pre {
    background-color: #e6e9ef;
    border-color: #ccd0da;
  }
  :root pre code {
    background-color: #e6e9ef;
    color: #4c4f69;
  }
  :root hr {
    border-style: solid;
    border-color: #bcc0cc;
  }
  :root .topnav,
  :root tr:nth-child(2n+1) {
    border-color: #ccd0da;
    background-color: #e6e9ef;
  }
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
  }
  :root ::selection {
    background-color: rgba(203, 166, 247, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #a6adc8 !important;
  }
  :root body {
    background-color: #1e1e2e;
    color: #cdd6f4;
  }
  :root #content h1,
  :root #content h2,
  :root #content h3,
  :root #content h4,
  :root #content h5,
  :root #content h6 {
    color: #cba6f7;
  }
  :root .pageheader {
    background-color: #181825;
    border-color: #11111b;
    color: #bac2de;
  }
  :root .pageheader .actions ul li a,
  :root input[type="submit"] {
    background-color: transparent;
    color: #cba6f7;
    border-color: #cba6f7;
  }
  :root input#searchbox {
    color: #bac2de;
    background-color: #6c7086;
    border-color: #7f849c;
    box-shadow: none;
  }
  :root input#searchbox:focus {
    border-color: #cba6f7;
    outline-color: none;
    outline-style: none;
  }
  :root .headerpath .title {
    color: #bac2de;
  }
  :root a:link {
    color: #89b4fa;
  }
  :root a:visited {
    color: #b4befe;
  }
  :root code {
    background-color: #11111b;
    color: #cdd6f4;
  }
  :root pre {
    background-color: #181825;
    border-color: #313244;
  }
  :root pre code {
    background-color: #181825;
    color: #cdd6f4;
  }
  :root hr {
    border-style: solid;
    border-color: #45475a;
  }
  :root .topnav,
  :root tr:nth-child(2n+1) {
    border-color: #313244;
    background-color: #181825;
  }
}
